1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
9	use AtrioTeam\DigitalHub\Tags\Models\Tag;
10	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
11	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
12	use Illuminate\Console\Command;
13	use Illuminate\Support\Facades\DB;
14	use Illuminate\Support\Str;
15	use OpenSpout\Reader\XLSX\Reader;
16	
17	/**
18	 * Import dei tag anagrafica dei tessuti dal foglio "Tessuti" del file filtri
19	 * INTERIOR (`INTERIOR - materiali e tessuti filtri.xlsx`).
20	 *
21	 * Il foglio è a colonna singola: righe intestazione di blocco (Tipologia,
22	 * Colori, Proprietà, Categoria, Moodboard, Tipo disegno) seguite dai valori;
23	 * le righe separatore (`____`) e vuote vengono ignorate.
24	 *
25	 * Ogni blocco diventa una TagCategory (identificata dallo slug) dentro il
26	 * gruppo "Tag Tessuti Indoor" (entity_type=fabric, target=entity, Category1
27	 * Indoor), ogni valore un Tag della categoria. Idempotente: categorie e tag
28	 * esistenti vengono aggiornati.
29	 */
30	class ImportIndoorFiltriTessuti extends Command
31	{
32	    protected $signature = 'app:import-indoor-filtri-tessuti '
33	        . '{--file=storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx} '
34	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
35	
36	    protected $description = 'Import dei tag anagrafica tessuti dal file filtri INTERIOR (foglio "Tessuti")';
37	
38	    private const SHEET = 'Tessuti';
39	
40	    /**
41	     * Intestazioni di blocco (chiave normalizzata) → nome visualizzato della
42	     * TagCategory. Nel foglio compaiono con casing misto (es. "CATEGORIA").
43	     *
44	     * @var array<string, string>
45	     */
46	    private const BLOCKS = [
47	        'tipologia' => 'Tipologia',
48	        'colori' => 'Colori',
49	        'proprietà' => 'Proprietà',
50	        'categoria' => 'Categoria',
51	        'moodboard' => 'Moodboard',
52	        'tipo disegno' => 'Tipo disegno',
53	    ];
54	
55	    public function handle(): int
56	    {
57	        $file = (string) $this->option('file');
58	        if (! is_file($file)) {
59	            $this->error("File non trovato: {$file}");
60	
61	            return self::FAILURE;
62	        }
63	
64	        $blocks = $this->parseSheet($file);
65	        if ($blocks === null) {
66	            $this->error('Foglio "' . self::SHEET . '" non trovato nel file.');
67	
68	            return self::FAILURE;
69	        }
70	
71	        $stats = ['categories' => 0, 'tags' => 0];
72	
73	        DB::transaction(function () use ($blocks, &$stats): void {
74	            $group = $this->resolveGroup();
75	
76	            $categorySort = 0;
77	            foreach ($blocks as $blockName => $values) {
78	                $category = TagCategory::query()->updateOrCreate(
79	                    ['tag_group_id' => $group->id, 'slug' => Str::slug($blockName)],
80	                    ['name' => ['it' => $blockName, 'en' => $blockName], 'sort' => $categorySort++],
81	                );
82	                $stats['categories']++;
83	
84	                if ($this->option('fresh')) {
85	                    Tag::query()->where('tag_category_id', $category->id)->delete();
86	                }
87	
88	                foreach ($values as $value) {
89	                    /** @var Tag|null $tag */
90	                    $tag = Tag::query()
91	                        ->where('tag_category_id', $category->id)
92	                        ->where('name->it', $value)
93	                        ->first();
94	
95	                    if ($tag === null) {
96	                        $tag = new Tag();
97	                        $tag->tag_category_id = $category->id;
98	                    }
99	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
100	                    $tag->save();
101	                    $stats['tags']++;
102	                }
103	            }
104	        });
105	
106	        $this->info('Import tag tessuti completato.');
107	        $this->table(
108	            ['Metrica', 'Valore'],
109	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
110	        );
111	
112	        return self::SUCCESS;
113	    }
114	
115	    /**
116	     * Legge il foglio Tessuti e raggruppa i valori per blocco.
117	     * Ritorna null se il foglio non esiste.
118	     *
119	     * @return array<string, list<string>>|null
120	     */
121	    private function parseSheet(string $file): ?array
122	    {
123	        $blocks = null;
124	        $current = null;
125	
126	        $reader = new Reader();
127	        $reader->open($file);
128	        foreach ($reader->getSheetIterator() as $sheet) {
129	            if ($sheet->getName() !== self::SHEET) {
130	                continue;
131	            }
132	            $blocks = [];
133	
134	            foreach ($sheet->getRowIterator() as $row) {
135	                $cell = $row->getCells()[0] ?? null;
136	                $raw = $cell?->getValue();
137	                $value = is_scalar($raw) ? trim((string) $raw) : '';
138	
139	                // righe vuote e separatori (____) tra i gruppi di colori
140	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
141	                    continue;
142	                }
143	
144	                $blockName = self::BLOCKS[$this->normalize($value)] ?? null;
145	                if ($blockName !== null) {
146	                    $current = $blockName;
147	                    $blocks[$current] ??= [];
148	
149	                    continue;
150	                }
151	
152	                if ($current === null) {
153	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
154	
155	                    continue;
156	                }
157	
158	                $blocks[$current][] = $value;
159	            }
160	
161	            break;
162	        }
163	        $reader->close();
164	
165	        return $blocks;
166	    }
167	
168	    /**
169	     * Gruppo tag anagrafica dei tessuti Indoor (creato se assente).
170	     * Fallisce se la Category1 "Indoor" non esiste.
171	     */
172	    private function resolveGroup(): TagGroup
173	    {
174	        $indoor = Category1::query()->where('name->it', 'Indoor')->firstOrFail();
175	
176	        return TagGroup::query()
177	            ->where('entity_type', 'fabric')
178	            ->where('target', TagTarget::Entity)
179	            ->where('category_1_id', $indoor->id)
180	            ->first()
181	            ?? TagGroup::query()->create([
182	                'entity_type' => 'fabric',
183	                'target' => TagTarget::Entity,
184	                'category_1_id' => $indoor->id,
185	                'name' => ['it' => 'Tag Tessuti Indoor', 'en' => 'Indoor fabric tags'],
186	            ]);
187	    }
188	
189	    private function normalize(string $value): string
190	    {
191	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
192	    }
193	}
194

