docker exec atmosphera-hub_php php -r '
require "vendor/autoload.php";
$r = new OpenSpout\Reader\XLSX\Reader();
$r->open("storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx");
foreach ($r->getSheetIterator() as $s) {
  echo "SHEET: ".$s->getName()."\n";
  if ($s->getName() !== "Materiali") continue;
  foreach ($s->getRowIterator() as $row) {
    $c = $row->getCells()[0] ?? null;
    $v = $c?->getValue();
    echo var_export(is_scalar($v) ? trim((string)$v) : $v, true)."\n";
  }
}
$r->close();
'

